body {
    padding-bottom: 20px;
    overscroll-behavior-y: none;
}

/* Wrapping element */
/* Set some basic padding to keep content from hitting the edges */
.body-content {
    padding-left: 15px;
    padding-right: 15px;
}

.imageOverflowStyle {
    overflow-y: scroll;
    max-height: 300px;
}

.cursor {
    cursor: pointer;
}

/* The z-index of DownloadEdgeBanner and header are related. DownloadEdgeBanner should be higher than header but not as high as feedback popup*/
.Banner {
    align-items: center;
    display: inline-flex;
    margin: 0 auto;
    padding: 8px;
    background: white;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.8);
}

.BannerRedesigned {
    left: 0px;
    right: 0px;
    position: fixed;
    display: flex;
    align-items: center;
    justify-content: center;
}

.line-clamp {
    display: -webkit-box;
    -webkit-line-clamp: 5;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.shimmer {
    display: block;
    background-color: #e5e5e5;
    animation: blink 1.6s cubic-bezier(0.25, 0.1, 0.25, 1) infinite;
}

.disable-background-scroll {
    position: fixed;
    overflow-y: scroll;
    width: 100%;
}

.enable-scroll {
    position: static;
    overflow-y: auto;
}

@keyframes blink {
    0% {
        opacity: 0.5;
    }

    50% {
        opacity: 1;
    }

    100% {
        opacity: 0.5;
    }
}

/*TODO: Remove -ms-high-contrast during msEnableStoreUXRefresh feature cleanup */
@media (-ms-high-contrast: active), (forced-colors: active) {
    svg rect {
        stroke: WindowText;
    }

    svg:not([id^="FilterChipGlyph_"]) path {
        fill: WindowText;
    }

    .Banner {
        border: 1px solid;
    }

    .BannerRedesigned {
        border: 1px solid;
    }

    div[role="treeitem"]:hover svg rect,
    div[role="treeitem"][aria-selected="true"] svg rect {
        stroke: HighlightText;
    }

    div[role="treeitem"]:hover svg path,
    div[role="treeitem"][aria-selected="true"] svg path {
        fill: HighlightText;
    }

    button[direction="next"]:hover svg path,
    button[direction="previous"]:hover svg path {
        fill: HighlightText;
    }
}

/* For screen width less than 1035px size */
@media only screen and (max-width: 1035px) and (min-width: 860px) {
    .BannerRedesigned {
        position: unset;
    }
}
/*----------------------------------------------------------------------------------------------------------------*/

@media only screen and (min-width: 1024px) {
    #searchBoxInHeader {
        width: 100%;
        margin-inline-end: 16px;
    }
}

@media only screen and (max-width: 1024px) {
    #searchBoxInHeader {
        width: 100%;
        margin-inline-end: 24px;
    }
}

#aria-live-div-id {
    position: absolute;
    left: 0px;
    height: 1px;
    width: 0px;
    overflow: hidden;
}

.regular-media {
    margin: 0 auto;
}

.regular-media .media-video {
    max-width: 400px;
    max-height: 250px;
    display: flex;
}

.dialog-media .media-image {
    max-height: 65vh;
    height: auto !important;
    width: auto !important;
    object-fit: contain;
}

.incompatible {
    cursor: "hands";
    text-decoration: none;
}

.incompatible:hover {
    position: relative;
}

.incompatible span {
    display: none;
}

.incompatible:hover span {
    padding: 4px 8px;
